#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Generate Tests/Support/TestExpansion.hpp.

ASTERIA_EXPECT accepts its terms as separate macro arguments. The generated
macros expand them into a left-to-right `&&` chain of TestContext::Term calls,
preserving short-circuit evaluation while recording the first false term.
"""
import pathlib

MAXIMUM_TERMS = 64


def generate() -> str:
    lines = [
        '#ifndef ASTERIA_TESTS_SUPPORT_TEST_EXPANSION_HPP_INCLUDED',
        '#define ASTERIA_TESTS_SUPPORT_TEST_EXPANSION_HPP_INCLUDED',
        '',
        '// Generated by Tools/Test/GenerateTestExpansion.py; regenerate rather than edit.',
        '// Supports up to %d terms per ASTERIA_EXPECT.' % MAXIMUM_TERMS,
        '',
        '#define ASTERIA_TEST_DETAIL_CONCAT_IMPL(first, second) first##second',
        '#define ASTERIA_TEST_DETAIL_CONCAT(first, second) \\',
        '    ASTERIA_TEST_DETAIL_CONCAT_IMPL(first, second)',
        '#define ASTERIA_TEST_DETAIL_TERM(context, index, term) \\',
        '    (context).Term(static_cast<bool>(term), #term, index)',
    ]
    parameters = ', '.join('_%d' % index for index in range(1, MAXIMUM_TERMS + 1))
    counts = ', '.join(str(index) for index in range(MAXIMUM_TERMS, 0, -1))
    lines += [
        '#define ASTERIA_TEST_DETAIL_COUNT_IMPL(%s, count, ...) count' % parameters,
        '#define ASTERIA_TEST_DETAIL_COUNT(...) \\',
        '    ASTERIA_TEST_DETAIL_COUNT_IMPL(__VA_ARGS__, %s, 0)' % counts,
        '#define ASTERIA_TEST_DETAIL_TERMS_1(context, index, term) \\',
        '    ASTERIA_TEST_DETAIL_TERM(context, index, term)',
    ]
    for count in range(2, MAXIMUM_TERMS + 1):
        lines += [
            '#define ASTERIA_TEST_DETAIL_TERMS_%d(context, index, term, ...) \\' % count,
            '    ASTERIA_TEST_DETAIL_TERM(context, index, term) \\',
            '        && ASTERIA_TEST_DETAIL_TERMS_%d(context, (index) + 1, __VA_ARGS__)' % (count - 1),
        ]
    lines += [
        '#define ASTERIA_TEST_DETAIL_TERMS(context, ...) \\',
        '    ASTERIA_TEST_DETAIL_CONCAT( \\',
        '        ASTERIA_TEST_DETAIL_TERMS_, \\',
        '        ASTERIA_TEST_DETAIL_COUNT(__VA_ARGS__))(context, 1, __VA_ARGS__)',
        '',
        '#endif // ASTERIA_TESTS_SUPPORT_TEST_EXPANSION_HPP_INCLUDED',
    ]
    return '\n'.join(lines) + '\n'


def main() -> None:
    root = pathlib.Path(__file__).resolve().parents[2]
    output = root / 'Tests' / 'Support' / 'TestExpansion.hpp'
    output.write_text(generate())


if __name__ == '__main__':
    main()
